        <div class="crm-rel-modules">${modules.map((x,i)=>`<article><div class="crm-rel-module-icon">${icons[i]||'0'+(i+1)}</div><div><span class="crm-panel-kicker">${String(i+1).padStart(2,'0')}</span><h4>${esc(x.name)}</h4><p>${esc(x.description||descriptions[x.module_key]||'')}</p></div></article>`).join('')}</div>
